+  }
 }
+
+const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

@@ -0,0 +1,12 @@
+export const MAX_ATTEMPTS = 5;
+const BASE_MS = 1_000;
+const MAX_BACKOFF_MS = 30_000;
+
+/**
+ * Delay before retry number `attempt` (1-based): 1 s, 2 s, 4 s, 8 s, 16 s, capped at 30 s.
+ */
+export function backoffMs(attempt: number): number {
+  return Math.min(MAX_BACKOFF_MS, BASE_MS * 2 ** (attempt - 1));
+}

